== sys/git2/bindings.rs
/* automatically generated by rust-bindgen 0.73.2 */

== sys/git2/external.txt
git_error
git_indexer_progress
git_repository
git_str
== sys/git2/shims.c
/* Definitions of the shims declared in shims.h. */
#include "shims.h"
== sys/git2/shims.h
/*
 * Callable shims for the CLI's function-like macros, one `crustify_<NAME>` per macro, as
 * sys/libgit2/shims.h holds libgit2's. None yet.
 */
#ifndef CRUSTIFY_GIT2_SHIMS_H
#define CRUSTIFY_GIT2_SHIMS_H

#endif
== sys/git2/static_fns.c
== sys/git2/wrapper.h
/*
 * bindgen input of the `git2` link unit, the CLI executable (src/cli): its headers, as its
 * TUs see them, on the include path CMake gives `git2_cli` (src/util, src/cli, include, the
 * build's gen_headers and the dependencies' includes), which campaign mode reads from the
 * variant's build.ninja and the bundled build from its compile_commands.json. The types of
 * libgit2 and src/util they name are `sys::libgit2`'s, as external.txt lists them.
 */
#include "common.h"     /* src/cli: git2_util.h, error.h, opt.h, opt_usage.h */
#include "cmd.h"        /* src/cli */
#include "progress.h"   /* src/cli */
#include "sighandler.h" /* src/cli */

#include "shims.h"
//! The raw bindings: one public module per link unit, generated by bindgen from the C under
//! `c/` and its `sys/<link-unit>/` input, as crustify's `bindgen` skill lays them out.
//!
//! Each module holds the committed `sys/<link-unit>/bindings.rs`, or the bindings the
//! `bindgen` feature regenerates into `OUT_DIR`. Only the items the link unit's
//! `allowlist.txt` names are generated, under their C names; callable macro shims from its
//! `shims.c` are bound as `crustify_<NAME>`. The C that is not translated yet is reached
//! through them.

#[cfg(not(all(target_arch = "x86_64", target_os = "linux", target_env = "gnu")))]
compile_error!(
    "the raw bindings are generated for x86_64-unknown-linux-gnu, the only target the crate \
     supports"
);

/// Raw bindings to libgit2's public API (`include/git2.h` and `include/git2/sys/*.h`, built
/// with `GIT_DEPRECATE_HARD`) and to the internal items its batches bind, the `libgit2` link
/// unit (`libgit2.so`).
#[expect(
    clippy::allow_attributes,
    reason = "bindgen's output follows C's names and shapes, so the generated module is exempt \
              from the workspace's lints"
)]
#[allow(
    nonstandard_style,
    unsafe_op_in_unsafe_fn,
    missing_docs,
    rust_2018_idioms,
    unreachable_pub,
    unused_qualifications,
    unused_lifetimes,
    let_underscore_drop,
    trivial_casts,
    trivial_numeric_casts,
    dead_code,
    unused_imports,
    clippy::correctness,
    clippy::all,
    clippy::pedantic,
    clippy::cargo,
    clippy::undocumented_unsafe_blocks,
    clippy::multiple_unsafe_ops_per_block,
    clippy::missing_safety_doc,
    clippy::unnecessary_safety_comment,
    clippy::unnecessary_safety_doc,
    clippy::mem_forget,
    clippy::allow_attributes_without_reason
)]
#[rustfmt::skip]
pub mod libgit2 {
    /// The version of libgit2 the bindings match, as its `pkg-config` file records it.
    pub const C_VERSION: &str = env!("CRUSTIFY_C_VERSION_LIBGIT2");

    #[cfg(all(not(crustify_regenerated), not(doctest)))]
    include!("../sys/libgit2/bindings.rs");
    #[cfg(all(crustify_regenerated, not(doctest)))]
    include!(concat!(env!("OUT_DIR"), "/libgit2/bindings.rs"));
    // The C comments bindgen keeps hold C: rustdoc collects doctests from a copy of the
    // bindings that holds them as plain comments.
    #[cfg(doctest)]
    include!(concat!(env!("OUT_DIR"), "/libgit2/bindings.doctest.rs"));
}

/// Raw bindings to the CLI's headers (`src/cli/*.h`), the `git2` link unit (the `git2`
/// executable), as its TUs see them. The types of libgit2 and `src/util` they name are
/// [`libgit2`]'s, re-exported here under their C names, as `sys/git2/external.txt` lists
/// them.
#[cfg(feature = "git2")]
#[expect(
    clippy::allow_attributes,
    reason = "bindgen's output follows C's names and shapes, so the generated module is exempt \
              from the workspace's lints"
)]
#[allow(
    nonstandard_style,
    unsafe_op_in_unsafe_fn,
    missing_docs,
    rust_2018_idioms,
    unreachable_pub,
    unused_qualifications,
    unused_lifetimes,
    let_underscore_drop,
    trivial_casts,
    trivial_numeric_casts,
    dead_code,
    unused_imports,
    clippy::correctness,
    clippy::all,
    clippy::pedantic,
    clippy::cargo,
    clippy::undocumented_unsafe_blocks,
    clippy::multiple_unsafe_ops_per_block,
    clippy::missing_safety_doc,
    clippy::unnecessary_safety_comment,
    clippy::unnecessary_safety_doc,
    clippy::mem_forget,
    clippy::allow_attributes_without_reason
)]
#[rustfmt::skip]
pub mod git2 {
    /// The version of libgit2 whose CLI the bindings match, as its `pkg-config` file records it.
    pub const C_VERSION: &str = env!("CRUSTIFY_C_VERSION_GIT2");

    /// The types `sys/git2/external.txt` lists, which the `libgit2` link unit's bindings own.
    pub use super::libgit2::{git_error, git_indexer_progress, git_repository, git_str};

    #[cfg(all(not(crustify_regenerated), not(doctest)))]
    include!("../sys/git2/bindings.rs");
    #[cfg(all(crustify_regenerated, not(doctest)))]
    include!(concat!(env!("OUT_DIR"), "/git2/bindings.rs"));
    // The C comments bindgen keeps hold C: rustdoc collects doctests from a copy of the
    // bindings that holds them as plain comments.
    #[cfg(doctest)]
    include!(concat!(env!("OUT_DIR"), "/git2/bindings.doctest.rs"));
}
[package]
name = "libgit2-crustify"
description = "Safe Rust wrappers over libgit2's public API."
edition.workspace = true
rust-version.workspace = true
version.workspace = true
license.workspace = true
repository.workspace = true
publish.workspace = true
# The raw bindings' link metadata, which dependents' build scripts read as `DEP_GIT2_*`.
links = "git2"
build = "build.rs"
# The packaged crate: the safe crate, its raw bindings and the C its bundled build reads
# (crustify's `bindgen` skill, Publishing).
include = [
    "/Cargo.toml",
    "/build.rs",
    "/README.md",
    "/src/**",
    "/sys/**",
    "/c/COPYING",
    "/c/CMakeLists.txt",
    "/c/cmake/**",
    "/c/include/**",
    "/c/src/CMakeLists.txt",
    "/c/src/cli/**",
    "/c/src/libgit2/**",
    "/c/src/util/**",
    "/c/deps/llhttp/**",
    "/c/deps/ntlmclient/**",
    "/c/deps/reftable/**",
    "/c/deps/xdiff/**",
]

[features]
# Every link unit, so that the campaign's builds, lints and tests, which take the default
# features, cover each one the campaign ports.
default = ["libgit2", "git2"]
# One feature per link unit; each gates its module in src/lib.rs, and src/sys.rs's when the
# link unit is optional.
libgit2 = []
# The CLI (src/cli), whose C links libgit2's: the bundled build compiles its objects, and
# the `shared` and `system` modes, whose libraries hold none, refuse it.
git2 = ["libgit2"]
# Regenerates the raw bindings into OUT_DIR from the headers of the C a build links, in
# place of the committed ones; campaign mode checks them against the committed ones
# (crustify's `bindgen` skill, Build modes).
bindgen = ["dep:bindgen"]
# Builds `c/` as shared libraries in place of static ones.
shared = []
# Links an install of libgit2, found through LIBGIT2_DIR or pkg-config, in place of `c/`.
system = []

[dependencies]
# By path, not by Git: trybuild replaces only the paths of dependencies declared by path
# with `$FFIBOX` in compile-fail snapshots. By the checkout's canonical path, which
# /opt/venv/share/ffibox links to: trybuild replaces the canonicalized path, while rustc
# prints the path as declared, so a path through the link leaves the snapshots' paths
# absolute. glibc-bindings takes it by Git, which the [patch] below points at this path,
# so the graph holds one ffibox.
ffibox = { version = "0.1.1", path = "/crustify-rs/ffibox" }
# libc's wrapper, the crustify-rs/glibc-crustify side campaign: pinned to a commit
# (`wrapper.pin` in crustify/artifacts/dependencies.json), and patched below to its clone
# beside this repository while the campaign extends it, by absolute path, which the batch
# worktrees under crustify/.worktrees resolve too.
glibc-bindings = { version = "0.1.0", git = "https://github.com/crustify-rs/glibc-crustify", rev = "6180870f2ddbc30a43e5687395eb4f13908b3cbf" }
pcre2-sys = "0.2"
nix = { version = "0.31.3", features = ["fs", "socket", "net", "poll", "process", "user", "feature", "signal", "mman", "time", "uio", "dir", "hostname"] }
flate2 = "1.1.11"
sha2 = "0.11.1"
hmac = "0.13.0"
md-5 = "0.11.0"
md4 = "0.11.0"
des = "0.9.0"
getrandom = "0.4.3"
rustls = "0.23.46"
rustls-webpki = "0.103.16"
pcre2 = "0.2.11"

[build-dependencies]
# Pinned exactly: the committed bindings are its output.
bindgen = { version = "=0.73.2", optional = true }
cc = "1.2"
pkg-config = "0.3"
serde_json = "1"

[dev-dependencies]
# The campaign's tests and gates regenerate the bindings, and check them against the
# committed ones; the crate's dependents build from the committed bindings.
libgit2-crustify = { path = ".", features = ["bindgen"] }
trybuild = "1.0"

[lints]
workspace = true

[[test]]
name = "ub_safe"
path = "tests/ub_safe/main.rs"

[[test]]
name = "ub_unsafe"
path = "tests/ub_unsafe/main.rs"

[[test]]
name = "equiv"
path = "tests/equiv/main.rs"

[[test]]
name = "unit_pub"
path = "tests/unit_pub/main.rs"

[workspace]
resolver = "3"
members = ["."]

[workspace.package]
edition = "2024"
rust-version = "1.100"
version = "0.1.0"
license = "GPL-2.0-only WITH GCC-exception-2.0"
repository = "https://github.com/crustify-rs/libgit2-crustify"
publish = false

[patch."https://github.com/crustify-rs/glibc-crustify"]
glibc-bindings = { path = "/target/glibc-crustify" }

[patch."https://github.com/crustify-rs/ffibox"]
ffibox = { path = "/crustify-rs/ffibox" }

[workspace.metadata.crustify]
nightly = "nightly-2026-10-08"
# The LLVM that generates the committed raw bindings, beside the bindgen pinned in
# [build-dependencies]: its libclang parses the headers, and its clang gives bindgen the
# system include dirs. Campaign mode loads exactly these, whatever drives the build (cargo
# bsan forces its own LLVM's), and checks the version clang reports (crustify's `bindgen`
# skill, Generation).
bindgen-llvm = "/usr/lib/llvm-18"
