//! `src/cli/opt.c`: the command-line argument parser of the `git2` CLI (`src/cli/opt.h`),
//! ported to Rust.
#![forbid(unsafe_code)]

// --- TEMPORARY STAND-INS for wave-186/batch-0's enum ports, removed at the rebase. ---
/// Stand-in.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[expect(missing_docs, reason = "stand-in")]
pub enum OptType {
    Bool = 1,
    Switch,
    Accumulator,
    Value,
    Literal,
    Arg,
    Args,
}
/// Stand-in.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub struct ParseFlags(u32);
#[expect(missing_docs, reason = "stand-in")]
impl ParseFlags {
    pub const DEFAULT: Self = Self(0);
    pub const GNU: Self = Self(1);
    pub const FORCE_GNU: Self = Self(2);
    #[must_use]
    pub const fn contains(self, o: Self) -> bool {
        self.0 & o.0 == o.0
    }
    #[must_use]
    pub const fn bits(self) -> u32 {
        self.0
    }
}
impl core::ops::BitOr for ParseFlags {
    type Output = Self;
    fn bitor(self, o: Self) -> Self {
        Self(self.0 | o.0)
    }
}
// --- END STAND-INS ---

/// The environment variable that asks programs for POSIX behaviour, which turns
/// [`ParseFlags::GNU`] off.
const POSIXLY_CORRECT: &str = "POSIXLY_CORRECT";

impl OptType {
    /// Whether a spec of this type is an option that its long name alone selects, `--name`:
    /// a [`Bool`](Self::Bool), a [`Switch`](Self::Switch) or a [`Value`](Self::Value).
    ///
    /// The parser matches a long argument against the specs of these types by name; the
    /// others are matched otherwise, or not by a long name: `--no-name` negates a `Bool`, and
    /// `--name=value` gives a `Value` its value, an [`Accumulator`](Self::Accumulator) has a
    /// short alias only, a bare `--` selects the [`Literal`](Self::Literal), and an
    /// [`Arg`](Self::Arg) or [`Args`](Self::Args) is a bare argument, never an option.
    ///
    /// The C macro takes a spec and reads its `type`; here the predicate is the type's, so
    /// that it reads `spec.type_().is_option()` once the spec is ported. Its body computes on
    /// its argument alone, so it is a `const fn`. A spec whose C `type` holds a value the enum
    /// does not name, which the C macro reports as no option, has no `OptType`: the spec's
    /// accessor refuses it before this predicate is reached.
    ///
    /// ```
    /// use libgit2_crustify::git2::src::cli::opt::OptType;
    ///
    /// assert!(OptType::Bool.is_option());
    /// assert!(OptType::Value.is_option());
    /// assert!(!OptType::Accumulator.is_option());
    /// assert!(!OptType::Args.is_option());
    /// ```
    ///
    /// Replaces `mac::spec_is_option_type`
    #[doc(alias = "spec_is_option_type")]
    #[must_use]
    #[inline]
    pub const fn is_option(self) -> bool {
        matches!(self, Self::Bool | Self::Switch | Self::Value)
    }
}

/// Whether a parser built with `flags` parses GNU-style, as `getopt_long` does, letting
/// options follow bare arguments (`file1 --help file2`), which it reorders in place: always
/// under [`ParseFlags::FORCE_GNU`]; under [`ParseFlags::GNU`] alone, unless the environment
/// sets `POSIXLY_CORRECT`, to any value, the empty one included; never without either. Flags
/// that ask nothing of the parsing style do not change it.
///
/// The C reads the variable with `getenv`, whose result it compares with NULL, which is
/// [`std::env::var_os`] returning `Some`: libc's `getenv` takes its `std` route. The variable
/// is read on every call, so a change to the environment between two parsers changes the
/// second one's style. On Windows the C reads it with `_wgetenv` where `UNICODE` is defined,
/// which `var_os` does too, and the crate is built for Linux alone.
///
/// ```
/// use libgit2_crustify::git2::src::cli::opt::{ParseFlags, support_gnu_style};
///
/// assert!(support_gnu_style(ParseFlags::FORCE_GNU));
/// assert!(!support_gnu_style(ParseFlags::DEFAULT));
/// ```
///
/// Replaces `fn::support_gnu_style`
#[doc(alias = "support_gnu_style")]
#[must_use]
pub fn support_gnu_style(flags: ParseFlags) -> bool {
    if flags.contains(ParseFlags::FORCE_GNU) {
        return true;
    }
    flags.contains(ParseFlags::GNU) && std::env::var_os(POSIXLY_CORRECT).is_none()
}

