//! `src/cli/opt.c`: `OptType::is_option`, `spec_is_option_type`'s port, and
//! `support_gnu_style`, checked against the contracts their docs give. The module has no C
//! tests to carry over.
//!
//! `support_gnu_style` reads `POSIXLY_CORRECT`, which a test does not set in its own
//! process: setting the environment is unsafe while other threads may read it, as the
//! harness's do. The tests that depend on it run their body in a child process of their own
//! binary, whose environment the parent sets, and Miri, which spawns no process, ignores
//! them; it runs the others.

use std::process::Command;

use libgit2_crustify::git2::src::cli::opt::{OptType, ParseFlags, support_gnu_style};

/// Every type a spec can have: every constant of `cli_opt_type_t` but the `NONE` that ends
/// a spec list.
const TYPES: [OptType; 7] = [
    OptType::Bool,
    OptType::Switch,
    OptType::Accumulator,
    OptType::Value,
    OptType::Literal,
    OptType::Arg,
    OptType::Args,
];

/// The types a long name selects are exactly `Bool`, `Switch` and `Value`.
#[test]
fn only_bools_switches_and_values_are_options() {
    for ty in TYPES {
        let expected = matches!(ty, OptType::Bool | OptType::Switch | OptType::Value);
        assert_eq!(ty.is_option(), expected, "{ty:?}");
    }
}

/// The predicate is usable in constant evaluation.
#[test]
fn is_option_is_const() {
    const BOOL: bool = OptType::Bool.is_option();
    const ARGS: bool = OptType::Args.is_option();
    assert!(BOOL);
    assert!(!ARGS);
}

/// `FORCE_GNU` asks for GNU style whatever else the flags hold, and reads no environment.
#[test]
fn force_gnu_is_gnu_style() {
    assert!(support_gnu_style(ParseFlags::FORCE_GNU));
    assert!(support_gnu_style(ParseFlags::GNU | ParseFlags::FORCE_GNU));
}

/// Without `GNU` or `FORCE_GNU` the parser is POSIX, whatever the environment holds.
#[test]
fn no_style_flag_is_posix_style() {
    assert!(!support_gnu_style(ParseFlags::DEFAULT));
    assert!(!support_gnu_style(ParseFlags::default()));
}

/// The variable that tells the child process which environment its parent gave it.
const CHILD: &str = "CRUSTIFY_TEST_OPT_POSIXLY_CORRECT";

/// Runs `name`, a test of this module, alone in a child process whose `POSIXLY_CORRECT` is
/// `value`, or unset; the child knows it is one by [`CHILD`].
fn run_child(name: &str, value: Option<&str>) {
    let mut cmd = Command::new(std::env::current_exe().unwrap());
    cmd.args([
        &format!("src::cli::opt::{name}"),
        "--exact",
        "--test-threads=1",
    ]);
    match value {
        Some(value) => cmd.env("POSIXLY_CORRECT", value).env(CHILD, "set"),
        None => cmd.env_remove("POSIXLY_CORRECT").env(CHILD, "unset"),
    };
    let out = cmd.output().unwrap();
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(
        out.status.success() && stdout.contains("1 passed"),
        "child with POSIXLY_CORRECT={value:?} failed:\n{stdout}\n{}",
        String::from_utf8_lossy(&out.stderr)
    );
}

/// `GNU` alone asks for GNU style unless `POSIXLY_CORRECT` is set, to any value, the empty
/// one included, and `FORCE_GNU` ignores the variable.
#[test]
#[cfg_attr(miri, ignore = "spawns a process")]
fn gnu_yields_to_posixly_correct() {
    match std::env::var(CHILD).as_deref() {
        Ok("unset") => {
            assert!(support_gnu_style(ParseFlags::GNU));
            assert!(support_gnu_style(ParseFlags::FORCE_GNU));
            assert!(!support_gnu_style(ParseFlags::DEFAULT));
        }
        Ok("set") => {
            assert!(!support_gnu_style(ParseFlags::GNU));
            assert!(support_gnu_style(ParseFlags::FORCE_GNU));
            assert!(support_gnu_style(ParseFlags::GNU | ParseFlags::FORCE_GNU));
            assert!(!support_gnu_style(ParseFlags::DEFAULT));
        }
        _ => {
            let name = "gnu_yields_to_posixly_correct";
            run_child(name, None);
            run_child(name, Some("1"));
            run_child(name, Some(""));
            run_child(name, Some("0"));
        }
    }
}

