#[test]
#[cfg_attr(miri, ignore = "spawns a process")]
fn gnu_style_matches_the_c_in_each_environment() {
    let name = "src::cli::opt::gnu_style_matches_the_c_in_each_environment";
    if std::env::var_os(CHILD).is_some() {
        for flags in flag_cases() {
            let (rust, c) = (support_gnu_style(flags), c_support_gnu_style(flags.bits()));
            assert_eq!(rust, c, "{flags:?}");
            println!("STEP {} {rust}", flags.bits());
        }
        return;
    }
    let posix = [None, Some("1"), Some("")];
    for value in posix {
        let mut cmd = Command::new(std::env::current_exe().unwrap());
        cmd.args([name, "--exact", "--test-threads=1", "--nocapture"])
            .env(CHILD, "1");
        match value {
            Some(value) => cmd.env("POSIXLY_CORRECT", value),
            None => cmd.env_remove("POSIXLY_CORRECT"),
        };
        let out = cmd.output().unwrap();
        let stdout = String::from_utf8_lossy(&out.stdout);
        assert!(
            out.status.success() && stdout.contains("1 passed"),
            "child with POSIXLY_CORRECT={value:?} failed:\n{stdout}\n{}",
            String::from_utf8_lossy(&out.stderr)
        );
        let steps: Vec<_> = stdout
            .lines()
            .filter_map(|l| l.split_once("STEP ").map(|(_, step)| step.to_owned()))
            .collect();
        let gnu = value.is_none();
        assert_eq!(
            steps,
            ["0 false".to_owned(), format!("1 {gnu}"), "2 true".to_owned(), "3 true".to_owned()],
            "POSIXLY_CORRECT={value:?}"
        );
    }
}

/// A flag outside the style flags changes neither side's style: C ignores the bits it does
/// not test. Its environment is the test's own, which neither style flag here reads.
#[test]
#[cfg_attr(miri, ignore = "calls C")]
fn other_flags_do_not_change_the_style() {
    for extra in [1 << 2, 1 << 31, !0b11] {
        assert!(!c_support_gnu_style(extra));
        assert!(c_support_gnu_style(extra | ParseFlags::FORCE_GNU.bits()));
    }
}

