 'use std::ffi::{CString, c_char, c_uint};\nuse std::process::Command;\nuse std::{mem, ptr};\n\nuse libgit2_crustify::git2::src::cli::opt::{Kind, ParseFlags, Status, Usage, uses_gnu_style};')
mb=m[m.index('/// Every kind a spec in a list can have'):]
mb=mb.replace('KINDS','LISTED_KINDS')
assert 'LISTED_KINDS' not in s
s=s.rstrip('\n')+'\n\n'+mb
open(p,'w').write(s)
EOF
